-- Disciplinary moderation: cases, granular restrictions, appeals, evidence and immutable audit trail
create table if not exists public.moderation_cases(id uuid primary key default gen_random_uuid(),subject_user_id uuid not null references public.profiles(id),subject_creator_id uuid references public.creators(id),report_id uuid references public.safety_reports(id),reason_code text not null,summary text,status text not null default 'open' check(status in('open','reviewing','decided','appealed','closed')),opened_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),closed_at timestamptz);
create table if not exists public.moderation_actions(id uuid primary key default gen_random_uuid(),case_id uuid references public.moderation_cases(id),subject_user_id uuid not null references public.profiles(id),subject_creator_id uuid references public.creators(id),action_type text not null check(action_type in('warning','restriction','suspension','demonetization','content_removal','deactivation','permanent_ban')),reason_code text not null,internal_note text,user_message text,starts_at timestamptz not null default now(),ends_at timestamptz,status text not null default 'active' check(status in('scheduled','active','expired','revoked')),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),revoked_at timestamptz,revoked_by uuid references public.profiles(id));
create table if not exists public.account_restrictions(id uuid primary key default gen_random_uuid(),action_id uuid not null references public.moderation_actions(id) on delete cascade,subject_user_id uuid not null references public.profiles(id),scope text not null check(scope in('account','publish','live','comment','message','purchase','monetization','withdrawal')),starts_at timestamptz not null,ends_at timestamptz,is_active boolean not null default true,unique(action_id,scope));
create table if not exists public.moderation_evidence(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.moderation_cases(id) on delete cascade,evidence_type text not null,reference_id text,url text,note text,added_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.moderation_appeals(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.moderation_cases(id),action_id uuid references public.moderation_actions(id),appellant_id uuid not null references public.profiles(id),message text not null,status text not null default 'submitted' check(status in('submitted','reviewing','upheld','reduced','cancelled')),review_note text,reviewed_by uuid references public.profiles(id),created_at timestamptz not null default now(),reviewed_at timestamptz);
create table if not exists public.moderation_audit_log(id bigint generated always as identity primary key,case_id uuid references public.moderation_cases(id),action_id uuid references public.moderation_actions(id),actor_id uuid references public.profiles(id),event text not null,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists active_restrictions_idx on public.account_restrictions(subject_user_id,scope,is_active,ends_at);
create index if not exists moderation_actions_subject_idx on public.moderation_actions(subject_user_id,created_at desc);
alter table public.moderation_cases enable row level security; alter table public.moderation_actions enable row level security; alter table public.account_restrictions enable row level security; alter table public.moderation_evidence enable row level security; alter table public.moderation_appeals enable row level security; alter table public.moderation_audit_log enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$;
create policy "admins manage cases" on public.moderation_cases for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "admins manage actions" on public.moderation_actions for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "subject reads actions" on public.moderation_actions for select to authenticated using(subject_user_id=auth.uid() or public.is_admin());
create policy "admins manage restrictions" on public.account_restrictions for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "subject reads restrictions" on public.account_restrictions for select to authenticated using(subject_user_id=auth.uid() or public.is_admin());
create policy "admins manage evidence" on public.moderation_evidence for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "appeals visible" on public.moderation_appeals for select to authenticated using(appellant_id=auth.uid() or public.is_admin());
create policy "submit own appeal" on public.moderation_appeals for insert to authenticated with check(appellant_id=auth.uid());
create policy "admins update appeals" on public.moderation_appeals for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "admins audit" on public.moderation_audit_log for select to authenticated using(public.is_admin());
create policy "admins write audit" on public.moderation_audit_log for insert to authenticated with check(public.is_admin());
create or replace function public.has_active_restriction(p_scope text) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.account_restrictions r where r.subject_user_id=auth.uid() and r.scope in(p_scope,'account') and r.is_active=true and r.starts_at<=now() and (r.ends_at is null or r.ends_at>now()))$$;
